<script src="{{ asset('assets/js/dt5.min.js') }}"></script><script src="https://cdn.datatables.net/scroller/2.2.0/js/dataTables.scroller.min.js"></script><script src="{{ asset('assets/plugins/select2/select2.full.min.js') }}"></script>
<script>
$(function(){
    $('.report-select').select2({theme:'bootstrap-5',width:'100%'});
    const text=$.fn.dataTable.render.text(), money=value => new Intl.NumberFormat('id-ID',{maximumFractionDigits:0}).format(value);
    const amount=(value,type) => type==='display' ? (value===0 ? '—' : money(value)) : value;
    const table=$('#lain-report').DataTable({processing:true,serverSide:true,deferRender:true,ordering:false,searchDelay:450,pageLength:25,dom:'frti',scrollX:true,scrollY:'460px',scrollCollapse:true,scroller:{displayBuffer:3,serverWait:350},
        ajax:{url:@json(route('rekap.lain-lain')),data:data => {data.bulan=@json($bulan);data.tahun=@json($tahun);},error:xhr => {$('#retry-lain').removeClass('d-none');Swal.fire({icon:'error',title:'Rekap belum dapat dimuat',text:xhr.responseJSON?.errors ? Object.values(xhr.responseJSON.errors).flat().join('\n') : 'Periksa koneksi lalu coba muat ulang data.'});}},
        columns:[{data:'tanggal',render:text,searchable:false},{data:'uraian',render:text,className:'uraian-cell',createdCell:(cell,value) => {cell.title=value || '';}},{data:'masuk',render:amount,searchable:false,className:'text-end text-success'},{data:'keluar',render:amount,searchable:false,className:'text-end text-danger'},{data:'transfer_ke',render:text,defaultContent:'—'},{data:'bank',render:text,defaultContent:'—'}],
        language:{search:'Cari transaksi:',searchPlaceholder:'Uraian, penerima, atau bank…',processing:'Memuat transaksi…',emptyTable:'Belum ada transaksi lain-lain pada periode ini.',zeroRecords:'Tidak ada transaksi yang sesuai pencarian.',info:'Menampilkan _START_–_END_ dari _TOTAL_ transaksi',infoEmpty:'Tidak ada transaksi yang ditampilkan',infoFiltered:'(dari _MAX_ transaksi)'},
        drawCallback:function(){const totals=this.api().ajax.json()?.totals;if(totals){$('#summary-count').text(money(totals.count));['masuk','keluar'].forEach(key => {$('#summary-'+key).text('Rp '+money(totals[key]));$('#total-'+key).text(money(totals[key]));});}$('#retry-lain').addClass('d-none');}
    });$('#retry-lain').on('click',() => table.ajax.reload());
});
</script>
